import { createRequire } from 'module';
import { join } from 'path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.locator('#jogo').scrollIntoViewIfNeeded();
await page.locator('#game-start').click();
await page.waitForTimeout(200);
await page.evaluate(() => document.activeElement?.blur());
await page.locator('#street-canvas').focus();

const held = { left: false, right: false };
async function setDir(dir) {
  if (dir === 'left' && !held.left) { await page.keyboard.down('ArrowLeft'); held.left = true; }
  if (dir !== 'left' && held.left) { await page.keyboard.up('ArrowLeft'); held.left = false; }
  if (dir === 'right' && !held.right) { await page.keyboard.down('ArrowRight'); held.right = true; }
  if (dir !== 'right' && held.right) { await page.keyboard.up('ArrowRight'); held.right = false; }
}
let lastJump = 0;
let maxScore = 0;
let runs = 0;
const started = Date.now();
while (Date.now() - started < 75000) {
  const s = await page.evaluate(() => {
    const g = window.__nightRun;
    return g && { state: g.state, score: g.score, lives: g.lives, timeLeft: g.timeLeft, x: g.playerX, y: g.playerY, onGround: g.onGround, patches: g.patches, obstacles: g.obstacles, powerups: g.powerups };
  });
  if (!s) break;
  if (s.state === 'won' || s.state === 'lost') break;
  maxScore = Math.max(maxScore, s.score);
  const px = s.x + 20;
  // choose nearest collectible ahead (patches, powerups)
  const items = [...s.patches, ...s.powerups].filter(i => i.x > px - 15).sort((a, b) => a.x - b.x);
  const target = items[0];
  let dir = 'none';
  if (target) {
    const tx = target.x + (target.width || 27) / 2;
    const dx = tx - px;
    if (dx > 12) dir = 'right';
    else if (dx < -12) dir = 'left';
    const high = target.y < 260;
    const near = Math.abs(dx) < 85;
    if (high && near && s.onGround) {
      await page.keyboard.press('Space');
      lastJump = Date.now();
    }
  }
  // obstacle avoidance: jump if obstacle is close ahead and we're grounded
  const danger = s.obstacles.find(o => o.x + o.width > px - 5 && o.x < px + 95);
  if (danger && s.onGround && Date.now() - lastJump > 500) {
    await page.keyboard.press('Space');
    lastJump = Date.now();
  }
  // jump for powerups roughly
  await setDir(dir);
  // sample
  if (s.score > maxScore) console.log('score', s.score, 'time', s.timeLeft.toFixed(1), 'lives', s.lives);
  await page.waitForTimeout(45);
}
await setDir('none');
const final = await page.evaluate(() => { const g = window.__nightRun; return { state: g.state, score: g.score, lives: g.lives, timeLeft: g.timeLeft }; });
console.log('FINAL', final, 'errors', errors);
await page.screenshot({ path: '/tmp/opencode/screens/game-autoplay.jpg', type: 'jpeg', quality: 82 });
await browser.close();
